function scoreR46(rows){
 if(!rows.length)return {status:"NO_COMMON_PREDICTIONS",gate_pass:false};
 const fold=xs=>{const s={N:xs.length,mse_base:0,mse_context:0,value_base:0,value_context:0,advantage:0};for(const r of xs){for(const k of ["y","pred_base","pred_context"])if(!Number.isFinite(r[k]))throw Error("score finite");s.mse_base+=(r.y-r.pred_base)**2;s.mse_context+=(r.y-r.pred_context)**2;s.value_base+=r.pred_base>0?r.y:0;s.value_context+=r.pred_context>0?r.y:0;}for(const k of ["mse_base","mse_context","value_base","value_context"])s[k]/=xs.length;s.advantage=s.value_context-s.value_base;return s;};
 const daily=new Map;for(const r of rows){if(!daily.has(r.origin))daily.set(r.origin,[]);daily.get(r.origin).push(r);}
 const days=[...daily].map(([origin,xs])=>({origin,...fold(xs)})),all=fold(rows);
 const day={N:days.length};for(const k of ["mse_base","mse_context","value_base","value_context","advantage"])day[k]=days.reduce((s,d)=>s+d[k],0)/days.length;
 const years={};for(let y=2021;y<=2025;y++){const rs=rows.filter(r=>new Date(r.origin).getUTCFullYear()===y),ds=days.filter(d=>new Date(d.origin).getUTCFullYear()===y);years[y]={rows:rs.length,origin_days:ds.length,node:rs.length?fold(rs):null,day:ds.length?Object.fromEntries(["mse_base","mse_context","value_base","value_context","advantage"].map(k=>[k,ds.reduce((s,d)=>s+d[k],0)/ds.length])):null};}
 const yearlyJoint=Object.values(years).filter(v=>v.day&&v.day.mse_context<v.day.mse_base&&v.day.advantage>0).length;
 const gates={sample_nodes:rows.length>=1000,sample_days:days.length>=365,years_coverage:Object.values(years).every(v=>v.origin_days>=30),node_MSE:all.mse_context<all.mse_base,day_MSE:day.mse_context<day.mse_base,node_value:all.value_context>0&&all.advantage>0,day_value:day.value_context>0&&day.advantage>0,years4of5:yearlyJoint>=4};
 return {status:"PAIRED_MATURE_COMMON_SCORE",node:all,day,years,yearlyJoint,gates,gate_pass:Object.values(gates).every(Boolean),limits:["Myopic counterfactual 4h continuation values, not a capital/account return","Overlapping shadow nodes/days not independent samples","Observed adaptive historical development, not OOS"]};
}

